<?php $u=require_user();$items=q('SELECT c.*,p.nombre AS p_nombre,p.precio AS p_precio,p.foto AS p_foto,p.cantidad_almacen,f.nombre AS f_nombre,f.precio AS f_precio,pr.nombre AS formato FROM carrito c LEFT JOIN productos p ON c.producto_id=p.id LEFT JOIN formulas f ON c.formula_id=f.id LEFT JOIN presentaciones pr ON f.presentacion_id=pr.id WHERE c.usuario_id=? ORDER BY c.id DESC',[$u['id']])->fetchAll();$total=0;?><div class="container py-5"><div class="kicker mb-3">TU SELECCIÓN</div><h1 style="font-size:3.5rem">Mi carrito</h1><?php if(!$items): ?><div class="surface text-center empty-state mt-4"><h3>Tu carrito está vacío</h3><p>Explora productos o crea una mezcla personalizada.</p><a class="btn btn-brand" href="index.php?page=catalogo">Ir al catálogo</a></div><?php else: ?><div class="row g-4 mt-2"><div class="col-lg-8"><div class="surface p-3 p-md-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Producto</th><th>Precio</th><th>Cantidad</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($items as $item): $name=$item['p_nombre']??$item['f_nombre'];$price=(float)($item['p_precio']??$item['f_precio']);$total+=$price*(int)$item['cantidad']; ?><tr><td><div class="d-flex align-items-center gap-2"><img class="mini-product" src="<?=h($item['producto_id']?product_image(['foto'=>$item['p_foto']]):'assets/img/pack.svg')?>" alt=""><div class="fw-semibold"><?=h($name)?><div class="small-muted"><?=h($item['formato']??'Catálogo')?></div></div></div></td><td><?=money($price)?></td><td><form method="post" action="actions.php" class="d-flex gap-2"><input type="hidden" name="action" value="cart_qty"><?=csrf_input()?><input type="hidden" name="carrito_id" value="<?=(int)$item['id']?>"><input class="form-control quantity-control" type="number" min="1" max="99" name="cantidad" value="<?=(int)$item['cantidad']?>"><button type="submit" class="btn btn-sm btn-outline-brand">↻</button></form></td><td><?=money($price*(int)$item['cantidad'])?></td><td><form method="post" action="actions.php"><input type="hidden" name="action" value="cart_remove"><?=csrf_input()?><input type="hidden" name="carrito_id" value="<?=(int)$item['id']?>"><button class="btn btn-sm btn-outline-danger" aria-label="Quitar">×</button></form></td></tr><?php endforeach ?></tbody></table></div></div></div><div class="col-lg-4"><div class="surface p-4"><h3>Resumen</h3><div class="d-flex justify-content-between my-4"><span>Subtotal</span><strong><?=money($total)?></strong></div><div class="d-flex justify-content-between my-4"><span>Envío</span><span>No incluido (demo)</span></div><hr><div class="d-flex justify-content-between mb-4"><h5>Total</h5><h5><?=money($total)?></h5></div><form method="post" action="actions.php"><input type="hidden" name="action" value="checkout"><?=csrf_input()?><label class="form-label">Dirección de entrega</label><textarea name="direccion_envio" required rows="3" class="form-control mb-3" maxlength="450"><?=h($u['direccion_postal'])?></textarea><button class="btn btn-brand w-100" data-confirm="¿Confirmas la compra simulada?" type="submit">Finalizar compra →</button></form><p class="small-muted mt-3">Esta acción sí descuenta stock y guarda el historial en la base de datos, pero <strong>no procesa pagos reales</strong>.</p></div></div></div><?php endif ?></div>
